{"command":"cat <<'EOF' > main.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <unistd.h>
#include <zlib.h>
#include <pthread.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <utime.h>
#include <sys/time.h>
#include <dirent.h>

#define DEFAULT_BLOCKSIZE (128 * 1024)
#define MAX_DICT_SIZE 32768

typedef struct job_t {
    long seq;
    unsigned char *in_buf;
    size_t in_size;
    unsigned char *dict_buf;
    size_t dict_size;
    unsigned char *out_buf;
    size_t out_size;
    size_t out_capacity;
    uint32_t crc;
    int is_last;
    struct job_t *next;
} job_t;

int g_level = 6;
int g_processes = 0;
size_t g_block_size = DEFAULT_BLOCKSIZE;
int g_keep = 0;
int g_force = 0;
int g_stdout = 0;
int g_decompress = 0;
int g_format = 0; // 0: gzip, 1: zlib, 2: zip
int g_independent = 0;
int g_verbose = 0;
int g_quiet = 0;
int g_no_name = 0;
int g_no_time = 0;
char *g_suffix = NULL;
int g_recursive = 0;
int g_list = 0;
int g_test = 0;

pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;
job_t *job_queue = NULL;
int threads_running = 1;

pthread_mutex_t out_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t out_cond = PTHREAD_COND_INITIALIZER;
long next_out_seq = 0;
job_t *finished_jobs = NULL;

void *compress_worker(void *arg) {
    while (1) {
        job_t *job = NULL;
        pthread_mutex_lock(&queue_mutex);
        while (job_queue == NULL && threads_running)
            pthread_cond_wait(&queue_cond, &queue_mutex);
        if (job_queue == NULL && !threads_running) {
            pthread_mutex_unlock(&queue_mutex);
            break;
        }
        job = job_queue;
        job_queue = job->next;
        pthread_mutex_unlock(&queue_mutex);

        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;
        deflateInit2(&strm, g_level, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
        if (job->dict_buf && job->dict_size > 0)
            deflateSetDictionary(&strm, job->dict_buf, job->dict_size);
        job->out_capacity = job->in_size + (job->in_size >> 3) + 64;
        job->out_buf = malloc(job->out_capacity);
        strm.next_in = job->in_buf;
        strm.avail_in = job->in_size;
        strm.next_out = job->out_buf;
        strm.avail_out = job->out_capacity;
        deflate(&strm, job->is_last ? Z_FINISH : Z_SYNC_FLUSH);
        job->out_size = job->out_capacity - strm.avail_out;
        job->crc = crc32(0L, Z_NULL, 0);
        job->crc = crc32(job->crc, job->in_buf, job->in_size);
        deflateEnd(&strm);

        pthread_mutex_lock(&out_mutex);
        job->next = finished_jobs;
        finished_jobs = job;
        pthread_cond_broadcast(&out_cond);
        pthread_mutex_unlock(&out_mutex);
    }
    return NULL;
}

// Helper to write gzip header/trailer
void write_gzip_header(FILE *out, const char *filename, struct stat *st) {
    unsigned char h[10] = {0x1f, 0x8b, 8, 0, 0, 0, 0, 0, 0, 3};
    if (filename && !g_no_name) h[3] = 0x08;
    if (st && !g_no_time) {
        uint32_t m = (uint32_t)st->st_mtime;
        h[4] = m & 0xff; h[5] = (m >> 8) & 0xff; h[6] = (m >> 16) & 0xff; h[7] = (m >> 24) & 0xff;
    }
    h[8] = (g_level == 9 ? 2 : (g_level == 1 ? 4 : 0));
    fwrite(h, 1, 10, out);
    if (filename && !g_no_name) {
        const char *p = strrchr(filename, '/');
        p = p ? p + 1 : filename;
        fwrite(p, 1, strlen(p) + 1, out);
    }
}

void write_gzip_trailer(FILE *out, uint32_t crc, uint32_t isize) {
    unsigned char t[8];
    t[0] = crc & 0xff; t[1] = (crc >> 8) & 0xff; t[2] = (crc >> 16) & 0xff; t[3] = (crc >> 24) & 0xff;
    t[4] = isize & 0xff; t[5] = (isize >> 8) & 0xff; t[6] = (isize >> 16) & 0xff; t[7] = (isize >> 24) & 0xff;
    fwrite(t, 1, 8, out);
}

