{"command":"cat <<'EOF' >> main.c

void decompress_file(const char *in_name, const char *out_name) {
    gzFile in = in_name ? gzopen(in_name, "rb") : gzdopen(fileno(stdin), "rb");
    FILE *out = out_name ? fopen(out_name, "wb") : stdout;
    unsigned char buf[65536];
    int n;
    while ((n = gzread(in, buf, sizeof(buf))) > 0) {
        fwrite(buf, 1, n, out);
    }
    gzclose(in);
    if (out_name) fclose(out);
}

void process_file(const char *in_name) {
    char out_name[1024];
    if (g_stdout || in_name == NULL) {
        if (g_decompress) decompress_file(in_name, NULL);
        else compress_file(in_name, NULL);
    } else {
        if (g_decompress) {
            strncpy(out_name, in_name, sizeof(out_name));
            char *ext = strrchr(out_name, '.');
            if (ext && strcmp(ext, g_suffix ? g_suffix : ".gz") == 0) *ext = '\0';
            else strcat(out_name, ".out");
        } else {
            snprintf(out_name, sizeof(out_name), "%s%s", in_name, g_suffix ? g_suffix : ".gz");
        }
        if (g_decompress) decompress_file(in_name, out_name);
        else compress_file(in_name, out_name);
        if (!g_keep) unlink(in_name);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    g_processes = sysconf(_SC_NPROCESSORS_ONLN);

    static struct option long_opts[] = {
        {"help", no_argument, 0, 'h'},
        {"version", no_argument, 0, 'V'},
        {"decompress", no_argument, 0, 'd'},
        {"keep", no_argument, 0, 'k'},
        {"force", no_argument, 0, 'f'},
        {"stdout", no_argument, 0, 'c'},
        {"processes", required_argument, 0, 'p'},
        {"blocksize", required_argument, 0, 'b'},
        {"recursive", no_argument, 0, 'r'},
        {"independent", no_argument, 0, 'i'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "0123456789hVdkfcp:b:ri", long_opts, NULL)) != -1) {
        if (opt >= '0' && opt <= '9') g_level = opt - '0';
        else switch (opt) {
            case 'h': printf("Usage: pigz [options] [files ...]\n"); return 0;
            case 'V': printf("pigz 2.8\n"); return 0;
            case 'd': g_decompress = 1; break;
            case 'k': g_keep = 1; break;
            case 'f': g_force = 1; break;
            case 'c': g_stdout = 1; break;
            case 'p': g_processes = atoi(optarg); break;
            case 'b': g_block_size = atoi(optarg) * 1024; break;
            case 'r': g_recursive = 1; break;
            case 'i': g_independent = 1; break;
        }
    }

    if (optind == argc) {
        process_file(NULL);
    } else {
        for (int i = optind; i < argc; i++) {
            process_file(argv[i]);
        }
    }
    return 0;
}
EOF
