            case 'k': g_keep = 1; break;
            case 'f': g_force = 1; break;
            case 'c': g_stdout = 1; break;
            case 'p': g_processes = atoi(optarg); break;
            case 'b': g_block_size = atoi(optarg) * 1024; break;
            case 'i': g_independent = 1; break;
            case 'z': g_format = 1; break;
            case 'K': g_format = 2; break;
            case 'n': g_no_name = 1; g_no_time = 1; break;
            case 'm': g_no_time = 1; break;
        }
    }
    if (optind == argc) process_file(NULL);
    else for (int i = optind; i < argc; i++) process_file(argv[i]);
    return 0;
}
